{
  "passageId": "meaning-internalism-externalism",
  "items": [
    {
      "id": "R1",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "인간의 생각과 느낌에 기반한 의미관을 ‘의미 내재주의’라고 명명한다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "레몬에 관한 설명은 대상에 대한 인식의 일부를 의미로 제시하는 구체적 사례이다."
    },
    {
      "id": "R3",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "레몬의 색깔과 맛에 관한 설명은 지시체에 대한 인식을 기술하는 기술구의 사례이다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "기술구가 의미를 결정한다는 설명에서 의미를 아는 것은 기술구를 아는 것이라는 판단이 도출된다."
    },
    {
      "id": "R5",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "퍼트넘은 기술구가 의미를 결정한다는 내재주의의 주장을 객관성이 부족하다는 이유로 문제 삼는다."
    },
    {
      "id": "R6",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "의미의 결정 기반을 외부 세계로 보는 외재주의와 인간의 의식으로 보는 내재주의의 견해가 다르다."
    },
    {
      "id": "R7",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "퍼트넘은 외부 세계가 의미를 결정한다는 주장을 논증하려는 목적으로 사고 실험을 제시한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "앞서 소개한 쌍둥이 지구 사고 실험의 설정과 논증 내용을 구체적으로 풀어 설명한다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 지구의 물이 같은 이름과 감각적 속성을 갖는다는 설정이 사람들의 인식도 동일하다는 판단을 뒷받침한다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "두 지구에서 물을 같은 용도로 사용한다는 사실로부터 물에 대한 생각과 느낌이 동일하다는 결론을 이끈다."
    },
    {
      "id": "R11",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 지구에서 물이라고 불리는 대상이 화학식이라는 같은 기준에서 H2O와 XYZ로 다르다."
    },
    {
      "id": "R12",
      "type": "CONDITION",
      "otherName": "",
      "reason": "쌍둥이 지구의 물이 지구의 물과 다른 물질로 밝혀진다는 조건에서 두 단어의 의미가 다르다고 설명한다."
    },
    {
      "id": "R13",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "물에 대한 기술구가 동일할 수 있음을 인정하면서도 그것이 의미의 동일성으로 이어지지는 않는다고 제한한다."
    },
    {
      "id": "R14",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "두 지구 사람들이 물에 대해 같은 인식을 갖더라도 물질 자체와 단어의 의미까지 같은 것은 아니라고 설명한다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "물에 대한 기술구는 같아도 물질은 다른 구체적 설정에서 인식이 같아도 대상은 다를 수 있다는 일반적 성질을 제시한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인식이 동일해도 대상은 다를 수 있다는 사고 실험의 결과를 외부 대상에 의한 의미 결정 주장의 근거로 삼는다."
    },
    {
      "id": "R17",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "기술구가 같아도 의미는 다르다는 사고 실험의 판단으로 기술구가 의미를 결정한다는 내재주의를 반박한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "외부 세계가 의미를 결정한다는 주장을 대상의 실제적 본성이 결정한다는 설명으로 구체화한다."
    },
    {
      "id": "R19",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "의미 결정 요인으로 제시한 ‘실제적 본성’의 뜻을 대상 속에 숨겨진 본질적 구조로 풀이한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "금이라는 명칭이 겉모습이 아닌 실제적 본성에 달려 있다는 사례로 의미 결정에 관한 설명을 구체화한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자연종 명사를 실제적 본성이 단어의 의미를 결정한다는 주장을 뒷받침하는 근거로 제시한다."
    },
    {
      "id": "R22",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "주장의 근거로 사용된 ‘자연종 명사’의 뜻을 자연에서 발견되는 대상을 나타내는 단어로 풀이한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "일반인이 전문가의 안내에 의존한다는 설명을 전문가의 금 판별과 일반인의 단어 사용으로 상세히 풀어 준다."
    },
    {
      "id": "R24",
      "type": "PROCESS",
      "otherName": "",
      "reason": "전문가가 금을 구별한 결과와 지식을 바탕으로 일반인이 금이라는 단어를 사용하는 다음 단계가 이어진다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "금의 전문가와 일반인이 수행하는 협업은 언어적 노동 분업이라는 일반적 개념의 구체적 사례이다."
    },
    {
      "id": "R26",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "구체적인 반박 내용은 없지만 퍼트넘의 외재주의를 문제 삼는 비판적 입장들이 있음을 제시한다."
    },
    {
      "id": "R27",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "퍼트넘의 주장에 비판이 존재함을 인정하면서도 새로운 관점을 제시했다는 의의는 인정한다."
    },
    {
      "id": "R28",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "퍼트넘의 외재주의에 대해 대상 기반의 객관적 의미를 추구한 새로운 관점이라는 의의를 부여한다."
    },
    {
      "id": "R29",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "대상을 기반으로 의미를 찾는 퍼트넘의 관점과 인간의 인식을 기반으로 의미를 설명하는 전통적 내재주의를 대비한다."
    }
  ]
}

